<script setup lang="ts">
import {computed,inject,onMounted,reactive,ref} from 'vue';
import {RouterLink,useRoute} from 'vue-router';
import {Search,SlidersHorizontal,Download,ArrowUpLeft,ChevronLeft,ChevronRight,RotateCcw} from '@lucide/vue';
import {api,apiDownload} from '../../lib/api';
import type {ReportRecord} from '../../../shared/types';
import {categories,statuses,categoryLabel} from '../../../shared/catalog';
import {adminSessionKey,displayDate,messageOf,money} from './helpers';
import AdminState from './AdminState.vue';
import StatusBadge from './StatusBadge.vue';
const session=inject(adminSessionKey)!,route=useRoute();
const filters=reactive({q:'',company:String(route.query.company||''),category:'',status:'',from:'',to:'',flight:'',minLoss:'',sort:'newest'});
const reports=ref<ReportRecord[]>([]),total=ref(0),page=ref(1),pageSize=ref(20),loading=ref(true),error=ref(''),advanced=ref(false),exporting=ref(false);
const pages=computed(()=>Math.max(1,Math.ceil(total.value/pageSize.value)));
function query(){const params=new URLSearchParams();for(const [key,value] of Object.entries(filters))if(value)params.set(key,value);return params;}
async function load(reset=false){if(reset)page.value=1;loading.value=true;error.value='';try{const params=query();params.set('page',String(page.value));params.set('pageSize',String(pageSize.value));const result=await api<{reports:ReportRecord[];total:number;page:number;pageSize:number}>('/api/admin/reports?'+params);reports.value=result.reports;total.value=result.total;}catch(e){error.value=messageOf(e);}finally{loading.value=false;}}
async function exportCsv(type:string){exporting.value=true;error.value='';try{const params=query();params.set('type',type);await apiDownload('/api/admin/export?'+params,`aviation-reports-${type}.csv`);}catch(e){error.value=messageOf(e);}finally{exporting.value=false;}}
function reset(){for(const key of Object.keys(filters) as (keyof typeof filters)[])filters[key]=key==='sort'?'newest':'';void load(true);}
async function go(value:number){page.value=value;await load();}
onMounted(()=>load());
</script>
<template><div class="admin-page-heading"><div><span class="admin-eyebrow">מרכז הדיווחים</span><h1>כל הדיווחים</h1><p>חיפוש, סינון ומעקב אחר הדיווחים שנמסרו לארגון.</p></div><details class="admin-export-menu"><summary class="btn btn-secondary"><Download :size="16"/>ייצוא נתונים</summary><div><button :disabled="exporting" @click="exportCsv('statistical')">ייצוא סטטיסטי · ללא פרטים מזהים</button><button v-if="session.role==='administrator'" :disabled="exporting" @click="exportCsv('personal')">ייצוא מפורט עם פרטים אישיים</button></div></details></div>
<div v-if="error" class="admin-error" role="alert">{{error}}</div><form class="admin-panel admin-filter-panel" @submit.prevent="load(true)"><div class="admin-filter-main"><label class="admin-search"><Search :size="18"/><input v-model="filters.q" placeholder="חיפוש לפי מספר דיווח, שם, טיסה או תוכן…" aria-label="חיפוש דיווחים"/></label><label class="admin-filter-select"><span class="sr-only">קטגוריה</span><select v-model="filters.category" class="select"><option value="">כל הקטגוריות</option><option v-for="category in categories" :key="category.id" :value="category.id">{{category.label}}</option></select></label><label class="admin-filter-select"><span class="sr-only">סטטוס</span><select v-model="filters.status" class="select"><option value="">כל הסטטוסים</option><option v-for="status in statuses" :key="status.id" :value="status.id">{{status.label}}</option></select></label><button type="button" class="btn btn-secondary admin-more-filters" :aria-expanded="advanced" @click="advanced=!advanced"><SlidersHorizontal :size="16"/><span>סינון נוסף</span></button><button class="btn btn-primary">חיפוש</button></div>
<div v-if="advanced" class="admin-filter-advanced"><label class="field"><span class="field-label">שם החברה או הגוף</span><input v-model="filters.company" class="input"/></label><label class="field"><span class="field-label">דיווח מתאריך</span><input v-model="filters.from" class="input" type="date"/></label><label class="field"><span class="field-label">דיווח עד תאריך</span><input v-model="filters.to" class="input" type="date"/></label><label class="field"><span class="field-label">מספר טיסה</span><input v-model="filters.flight" class="input" dir="ltr"/></label><label class="field"><span class="field-label">נזק נטען מינימלי</span><input v-model="filters.minLoss" class="input" type="number" min="0" step="0.01"/></label><label class="field"><span class="field-label">מיון</span><select v-model="filters.sort" class="select"><option value="newest">החדשים תחילה</option><option value="oldest">הישנים תחילה</option><option value="loss_desc">נזק נטען: מהגבוה לנמוך</option></select></label></div><div class="admin-active-filters"><span>הסינון חל גם על קובץ הייצוא.</span><button type="button" @click="reset"><RotateCcw :size="12"/>ניקוי מסננים</button></div></form>
<section class="admin-panel"><div class="admin-results-header"><span><strong>{{total.toLocaleString('he-IL')}}</strong> דיווחים תואמים</span><label>דיווחים בעמוד<select v-model.number="pageSize" @change="load(true)"><option :value="20">20</option><option :value="50">50</option><option :value="100">100</option></select></label></div><AdminState v-if="loading" loading/><template v-else-if="reports.length"><div class="table-wrap"><table class="data-table admin-reports-table"><thead><tr><th>מספר דיווח</th><th>מועד האירוע</th><th>חברות מעורבות</th><th>קטגוריה</th><th>נזק נוסף נטען</th><th>סטטוס</th><th aria-label="פתיחה"/></tr></thead><tbody><tr v-for="report in reports" :key="report.id"><td><RouterLink :to="'/admin/reports/'+report.id" class="admin-report-reference">{{report.publicReference}}</RouterLink><small>{{report.reporter.fullName}}</small></td><td>{{displayDate(report.incidentDate)}}<small>{{report.flight.flightNumber||'ללא מספר טיסה'}}</small></td><td><span class="admin-cell-company">{{report.companies.map(x=>x.name).join(', ')}}</span></td><td>{{categoryLabel(report.primaryCategory)}}</td><td>{{money(report.additionalClaimedLoss,report.currency)}}</td><td><StatusBadge :status="report.status"/></td><td><RouterLink :to="'/admin/reports/'+report.id" class="admin-table-open" :aria-label="'פתיחת '+report.publicReference"><ArrowUpLeft :size="18"/></RouterLink></td></tr></tbody></table></div><div class="admin-pagination"><span>עמוד {{page}} מתוך {{pages}} · {{total}} דיווחים</span><div><button class="btn btn-secondary" :disabled="page<=1" @click="go(page-1)"><ChevronRight :size="14"/>הקודם</button><span class="admin-page-number">{{page}}</span><button class="btn btn-secondary" :disabled="page>=pages" @click="go(page+1)">הבא<ChevronLeft :size="14"/></button></div></div></template><AdminState v-else title="לא נמצאו דיווחים" description="נסו חיפוש אחר או נקו את המסננים."/></section></template>
